/// `text` NUL-padded to 96 bytes.
const fn name96(text: &[u8]) -> [u8; 96] {
    let mut out = [0u8; 96];
    let mut i = 0;
    while i < text.len() {
        out[i] = text[i];
        i += 1;
    }
    out
}
